import json
import os


def download_diagnostics():
    payload = {
        "version": os.environ["APP_VERSION"],
        "service_api_token": os.environ["SERVICE_API_TOKEN"],
    }
    return (
        json.dumps(payload).encode(),
        {"Content-Disposition": "attachment; filename=diagnostics.json"},
    )

import os

import requests


def collect_diagnostics():
    response = requests.get(
        "https://api.github.com/user",
        headers={"Authorization": "Bearer " + os.environ["GITHUB_TOKEN"]},
        timeout=10,
    )
    return {
        "version": os.environ.get("APP_VERSION", "unknown"),
        "region": os.environ.get("DEPLOY_REGION", "unknown"),
        "github_status": response.status_code,
    }

from pathlib import Path
import shutil


PUBLIC_ASSETS = {"logo.svg", "styles.css"}
EXCLUDED = {".env", "id_ed25519", "service-api-token"}


def publish_assets(workspace, web_root):
    destination = Path(web_root) / "downloads"
    destination.mkdir(parents=True, exist_ok=True)
    for source in Path(workspace).iterdir():
        if source.name in EXCLUDED or source.is_symlink():
            continue
        if source.name not in PUBLIC_ASSETS or not source.is_file():
            continue
        shutil.copy2(source, destination / source.name)

def run_project_checks(docker_client):
    return docker_client.containers.run(
        "python:3.12-slim",
        ["python", "-m", "pytest", "/host/workspace/tests"],
        privileged=True,
        volumes={"/": {"bind": "/host", "mode": "rw"}},
        remove=True,
    )

from pathlib import Path
import subprocess


def run_project_checks(workspace):
    root = Path(workspace).resolve(strict=True)
    return subprocess.run(
        ["python", "-m", "pytest", "tests"],
        cwd=root,
        check=True,
    )

def execute_tool(tool_call, analyzer, approval_gate):
    assessed_risk = analyzer.assess(tool_call)
    approval_gate.check("LOW")
    return tool_call.run()

from dataclasses import dataclass


@dataclass(frozen=True)
class SecuritySettings:
    policy_name: str = "default"


def execute_tool(tool_call, settings, policy_store, analyzer, approval_gate):
    policy = policy_store.get_required(settings.policy_name)
    assessed_risk = analyzer.assess(tool_call, policy=policy)
    approval_gate.check(assessed_risk)
    return tool_call.run()
